from elftools.elf.elffile import ELFFile
import binascii
path='{TARGET}'
with open(path,'rb') as f:
    elf=ELFFile(f)
    def vaddr_to_offset(vaddr):
        for seg in elf.iter_segments():
            if seg['p_type']!='PT_LOAD':
                continue
            va=seg['p_vaddr']; memsz=seg['p_memsz']
            if va <= vaddr < va+memsz:
                return seg['p_offset'] + (vaddr - va)
        return None
    for addr,name,size in [(0x402004,'usage',64),(0x402016,'Correct',16),(0x40201f,'Wrong',16),(0x402050,'table',64),(0x404030,'strcmp_ptr_or_str',64)]:
        off=vaddr_to_offset(addr)
        print(name,hex(addr),'off',hex(off) if off else None)
        f.seek(off)
        data=f.read(size)
        print(binascii.hexlify(data))
        print(data)
